Since Next.js components are isolated, you cannot rely on `useState` inside a single component to track the state of *all* tooltips. Instead, you must lift the state up to a Context Provider that wraps your entire application (or the specific layout where you want tooltips to work).

Here is the complete solution using **React Context** and **Tailwind CSS** (standard in Next.js).

### 1. Create the Context and Provider

First, create a file to manage the global state of the tooltips.

`context/TooltipContext.tsx`

```tsx
'use client'; // Required for Next.js App Router

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';

// Define the shape of a tooltip
interface TooltipData {
  id: string;
  content: string;
  position: 'top' | 'bottom' | 'left' | 'right';
}

interface TooltipContextType {
  activeTooltip: TooltipData | null;
  openTooltip: (data: TooltipData) => void;
  closeTooltip: () => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

export const TooltipProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [activeTooltip, setActiveTooltip] = useState<TooltipData | null>(null);

  const openTooltip = useCallback((data: TooltipData) => {
    // Optional: Add a small delay to prevent flickering if clicked rapidly
    // setTimeout(() => setActiveTooltip(data), 50); 
    setActiveTooltip(data);
  }, []);

  const closeTooltip = useCallback(() => {
    setActiveTooltip(null);
  }, []);

  return (
    <TooltipContext.Provider value={{ activeTooltip, openTooltip, closeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

### 2. Wrap Your Application

You must wrap your application in the `TooltipProvider`. In Next.js App Router, this usually goes in `layout.tsx`.

`app/layout.tsx`

```tsx
import { TooltipProvider } from '@/context/TooltipContext';
import './globals.css';

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body>
        {/* This wraps the entire app, making the context available everywhere */}
        <TooltipProvider>
          {children}
        </TooltipProvider>
      </body>
    </html>
  );
}
```

