        System.out.println("Ghost: 'Who dares disturb my slumber?'");

        System.out.println("What do you say?");
        System.out.println("1. 'I am lost.'");
        System.out.println("2. 'I seek the treasure.'");
        System.out.println("3. 'I am here to fight.'");

        System.out.print("Enter choice (1-3): ");
        int choice = scanner.nextInt();

        switch (choice) {
            case 1:
                System.out.println("Ghost: 'A lost soul? Then you may pass.'");
                // Logic to move to next scene
                break;
            case 2:
                System.out.println("Ghost: 'Greed will be your undoing.'");
                // Logic to trigger a trap
                break;
            case 3:
                System.out.println("Ghost: 'A warrior? I like that. Come closer.'");
                // Logic to start combat
                break;
            default:
                System.out.println("Invalid choice. Try again.");
                break;
        }

        scanner.close();
    }
}
