// 1. Create a generic SVG element with attributes
function createSVGElem({ type, attributes = {} }) {
  const xmlns = "http://www.w3.org/2000/svg";
  const elem = document.createElementNS(xmlns, type);

  for (const [attr, value] of Object.entries(attributes)) {
    elem.setAttribute(attr, value);
  }

  return elem;
}

// 2. Create the root SVG element with optional children
function createSVG({ children = [] }) {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  if (Array.isArray(children)) {
    children.forEach(child => svg.appendChild(child));
  } else if (children) {
    svg.appendChild(children);
  }
  return svg;
}
