#### 2. The Backend Code (`server.js`)

This code handles the API endpoint, performs the filtering logic, and formats the response.

```javascript
require('dotenv').config();
const express = require('express');
const { Pool } = require('pg');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

// Database Connection
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

// 1. Backend Filtering Function
// This function takes a query string and returns matching hotels
const searchHotels = async (query) => {
  if (!query || query.length < 2) return [];

  const client = await pool.connect();
  try {
    // We use ILIKE for case-insensitive search and % for wildcards
    // We limit results to 5 for performance in a real scenario
    const result = await client.query(
      `SELECT id, name, city, country, rating 
       FROM hotels 
       WHERE name ILIKE $1 
       ORDER BY name 
       LIMIT 5`,
      [`%${query}%`]
    );
    return result.rows;
  } catch (error) {
    console.error('Database Error:', error);
    throw error;
  } finally {
    client.release();
  }
};

// 2. API Endpoint
app.get('/api/hotels', async (req, res) => {
  const { q } = req.query; // 'q' stands for query

  try {
    const hotels = await searchHotels(q);
    res.json({
      status: 'success',
      data: hotels
    });
  } catch (error) {
    res.status(500).json({ status: 'error', message: 'Server error' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

