    d: {
        token: "USER_TOKEN",
        properties: {
            os: "Windows",
            browser: "Electron",
            device: "Desktop"
        },
        compress: true
    }
};

// Server Response
const readyPacket = {
    op: 10, // OP: READY
    d: {
        shard_id: 42,
        session_id: "SESSION_UUID",
        heartbeat_interval: 5000,
        heartbeat_gateway: "wss://discord.com/gateway"
    }
};
```

