// app/Http/Requests/SpecBuilder.php
class SpecBuilder
{
    public function __construct(
        public string $name,
        public array $rules = [],
        public array $messages = [],
        public array $attributes = [],
        public array $description = [],
    ) {}

    public function description(string $text): self
    {
        $this->description[] = $text;
        return $this;
    }

    public function rule(string $field, string $rule): self
    {
        $this->rules[$field] = $rule;
        return $this;
    }

    public function rules(array $rules): self
    {
        $this->rules = array_merge($this->rules, $rules);
        return $this;
    }

    public function message(string $field, string $message): self
    {
        $this->messages[$field] = $message;
        return $this;
    }

    public function attribute(string $field, string $attribute): self
    {
        $this->attributes[$field] = $attribute;
        return $this;
    }
}

// app/Http/Requests/Request.php
